using System.IO;
using System.Net;
using System.Security.Cryptography;
using System.Text;
using PixelTart.SelectionApi.Contracts;
namespace PixelTart.SelectionApi.Server;
public static class Program
{
 public static async Task Main(string[]args)
 {
  var builder=WebApplication.CreateBuilder(args);var root=Environment.GetEnvironmentVariable("PIXELTART_SELECTION_LOCALDEV_ROOT")??throw new InvalidOperationException("Explicit isolated service root required.");var ownerKey=Environment.GetEnvironmentVariable("PIXELTART_SELECTION_OWNER_KEY")??throw new InvalidOperationException("Explicit local owner creation key required.");if(ownerKey.Length<32)throw new InvalidOperationException("Owner key too short.");var port=int.TryParse(Environment.GetEnvironmentVariable("PIXELTART_SELECTION_LOCALDEV_PORT"),out var n)?n:5127;
  builder.WebHost.ConfigureKestrel(k=>{k.Listen(IPAddress.Loopback,port);k.Limits.MaxRequestBodySize=64*1024*1024;});builder.Logging.ClearProviders();builder.Services.AddSingleton(new LocalDevSelectionRepository(Path.Combine(root,"Data")));builder.Services.AddSingleton<ISelectionObjectStorage>(new LocalSelectionObjectStorage(Path.Combine(root,"Objects")));builder.Services.AddSingleton<LocalDevJpegVariantService>();
  var publicBase=Environment.GetEnvironmentVariable("PIXELTART_SELECTION_PUBLIC_BASE_URL")??$"http://127.0.0.1:{port}";if(!Uri.TryCreate(publicBase,UriKind.Absolute,out var canonical)||canonical.Scheme!="https"&&!(canonical.Scheme=="http"&&canonical.IsLoopback)||!string.IsNullOrEmpty(canonical.UserInfo)||canonical.AbsolutePath!="/"||!string.IsNullOrEmpty(canonical.Query)||!string.IsNullOrEmpty(canonical.Fragment))throw new InvalidOperationException("Invalid explicit public test base URL");
  Directory.CreateDirectory(root);var instanceFile=Path.Combine(root,"service-instance.id");if(!File.Exists(instanceFile)){using var instance=new FileStream(instanceFile,FileMode.CreateNew);var bytes=Encoding.UTF8.GetBytes(Guid.NewGuid().ToString("N"));instance.Write(bytes);}var instanceId=File.ReadAllText(instanceFile).Trim();
  var app=builder.Build();var audit=Path.Combine(root,"requests.jsonl");var auditGate=new SemaphoreSlim(1,1);
  app.Use(async(c,next)=>{c.Response.Headers.CacheControl="no-store";c.Response.Headers["Referrer-Policy"]="no-referrer";c.Response.Headers["X-Content-Type-Options"]="nosniff";c.Response.Headers["Content-Security-Policy"]="default-src 'self'; script-src 'self'; style-src 'self'; img-src 'self' blob:; frame-ancestors 'none'; base-uri 'none'";try{await next(c);}catch(SelectionApiException e){c.Response.StatusCode=e.StatusCode;await c.Response.WriteAsJsonAsync(new ApiProblem(e.Code,e.Message,c.TraceIdentifier));}catch(BadHttpRequestException e){c.Response.StatusCode=e.StatusCode;await c.Response.WriteAsJsonAsync(new ApiProblem("InvalidRequest","Invalid request body or size.",c.TraceIdentifier));}catch(OperationCanceledException){if(!c.Response.HasStarted)c.Response.StatusCode=499;}catch(Exception){if(!c.Response.HasStarted){c.Response.StatusCode=500;await c.Response.WriteAsJsonAsync(new ApiProblem("ServiceError","Local service operation failed; retry with the same identity.",c.TraceIdentifier));}}finally{await auditGate.WaitAsync();try{Directory.CreateDirectory(root);await File.AppendAllTextAsync(audit,System.Text.Json.JsonSerializer.Serialize(new{timeUtc=DateTimeOffset.UtcNow,method=c.Request.Method,path=c.Request.Path.Value,status=c.Response.StatusCode,traceId=c.TraceIdentifier})+"\n");}finally{auditGate.Release();}}});
  static string Access(HttpRequest r){var a=r.Headers.Authorization.ToString();return a.StartsWith("Bearer ",StringComparison.Ordinal)?a[7..]:"";}
  static bool Equal(string a,string b)=>CryptographicOperations.FixedTimeEquals(SHA256.HashData(Encoding.UTF8.GetBytes(a)),SHA256.HashData(Encoding.UTF8.GetBytes(b)));
  app.MapGet("/health/ready",()=>Results.Ok(new{ready=true,mode="LocalDevHttpV1",production=false,instanceId}));
  app.MapPost("/v1/selection-projects",async(CreateSelectionProjectRequest req,HttpRequest request,LocalDevSelectionRepository db,CancellationToken ct)=>{if(!Equal(request.Headers["X-Owner-Key"].ToString(),ownerKey))throw new SelectionApiException(401,"OwnerRequired","Desktop owner credential required.");return Results.Ok(await db.Create(req,request.Headers["Idempotency-Key"].ToString(),ct));});
  app.MapGet("/v1/selection-projects/{id:guid}",async(Guid id,HttpRequest req,LocalDevSelectionRepository db,CancellationToken ct)=>Results.Ok(await db.Get(id,Access(req),ct)));
  app.MapPost("/v1/selection-projects/{id:guid}/assets/{asset:guid}/proxy",async(Guid id,Guid asset,HttpRequest req,LocalDevSelectionRepository db,LocalDevJpegVariantService jpeg,ISelectionObjectStorage storage,CancellationToken ct)=>{await db.Get(id,Access(req),ct);if(req.ContentType!="image/jpeg")throw new SelectionApiException(415,"ProxyJpegRequired","Only JPEG proxy bytes accepted.");using var input=new MemoryStream();await req.Body.CopyToAsync(input,ct);var sha=Convert.ToHexString(SHA256.HashData(input.ToArray()));if(req.Headers["X-Content-SHA256"].ToString()!=sha||req.Headers["Idempotency-Key"].ToString()!=$"asset:{id:N}:{asset:N}:{sha}")throw new SelectionApiException(400,"UploadIdentityInvalid","Stable content identity required.");input.Position=0;var variants=await jpeg.CreateAsync(input,ct);return Results.Ok(await db.Upload(id,asset,Access(req),Uri.UnescapeDataString(req.Headers["X-Original-File-Name"].ToString()),sha,variants,storage,ct));});
  app.MapPost("/v1/selection-projects/{id:guid}/publish",async(Guid id,PublishWithRuleRequest body,HttpRequest req,LocalDevSelectionRepository db,CancellationToken ct)=>Results.Ok(await db.Publish(id,Access(req),body,publicBase,ct)));
  app.MapPost("/v1/selection-projects/{id:guid}/unpublish",async(Guid id,HttpRequest req,LocalDevSelectionRepository db,CancellationToken ct)=>Results.Ok(await db.Unpublish(id,Access(req),ct)));
  app.MapGet("/v1/selection-projects/{id:guid}/progress",async(Guid id,HttpRequest req,LocalDevSelectionRepository db,CancellationToken ct)=>Results.Ok(await db.Progress(id,Access(req),ct)));
  app.MapGet("/v1/selection-projects/{id:guid}/final-selection",async(Guid id,HttpRequest req,LocalDevSelectionRepository db,CancellationToken ct)=>Results.Ok(await db.Final(id,Access(req),ct)));
  app.MapDelete("/v1/selection-projects/{id:guid}/assets/{asset:guid}/cloud-copy",async(Guid id,Guid asset,HttpRequest req,LocalDevSelectionRepository db,CancellationToken ct)=>Results.Ok(await db.Delete(id,asset,Access(req),ct)));
  app.MapGet("/v1/client/selection/{pub}",async(string pub,HttpRequest req,LocalDevSelectionRepository db,CancellationToken ct)=>{var p=await db.Client(pub,Access(req),ct);return Results.Ok(LocalDevSelectionRepository.PublicView(p));});
  app.MapGet("/v1/client/selection/{pub}/assets",async(string pub,HttpRequest req,LocalDevSelectionRepository db,CancellationToken ct)=>Results.Ok(await db.Assets(pub,Access(req),ct)));
  app.MapGet("/v1/client/selection/{pub}/assets/{asset:guid}/{variant}",async(string pub,Guid asset,string variant,HttpRequest req,LocalDevSelectionRepository db,ISelectionObjectStorage storage,CancellationToken ct)=>{var key=await db.Media(pub,asset,Access(req),variant,ct);var stream=await storage.OpenReadAsync(key,ct)??throw new SelectionApiException(404,"MediaNotFound","Media unavailable.");return Results.Stream(stream,"image/jpeg");});
  app.MapPut("/v1/client/selection/{pub}/choices/{asset:guid}",async(string pub,Guid asset,SelectionChoiceRequest body,HttpRequest req,LocalDevSelectionRepository db,CancellationToken ct)=>Results.Ok(await db.Choose(pub,asset,Access(req),body,ct)));
  app.MapPost("/v1/client/selection/{pub}/confirm",async(string pub,ConfirmSelectionRequest body,HttpRequest req,LocalDevSelectionRepository db,CancellationToken ct)=>Results.Ok(await db.Confirm(pub,Access(req),body,ct)));
  app.MapGet("/s/{pub}",async(string pub,LocalDevSelectionRepository db,CancellationToken ct)=>{var status=await db.PublicStatus(pub,ct);if(status!=200)return Results.Content("<!doctype html><html lang=zh-CN><meta charset=utf-8><meta name=viewport content=width=device-width><title>相册链接不可用</title><body><h1>相册链接已失效或过期</h1><p>请联系摄影师获取新的受保护链接。</p></body></html>","text/html; charset=utf-8",statusCode:status);return Results.Content(await File.ReadAllTextAsync(Path.Combine(AppContext.BaseDirectory,"wwwroot","selection.html"),ct),"text/html; charset=utf-8");});
  app.MapGet("/selection-client.js",()=>Results.File(Path.Combine(AppContext.BaseDirectory,"wwwroot","selection-client.js"),"text/javascript"));app.MapGet("/selection-client.css",()=>Results.File(Path.Combine(AppContext.BaseDirectory,"wwwroot","selection-client.css"),"text/css"));await app.RunAsync();
 }
}
